anya: yep. added minimal examples. Python async snippet uses async for + simple backoff.

```python
# async streaming + backoff (minimal)
import asyncio
from redwood import AsyncClient, APIError

async def stream_ai(prompt):
    async with AsyncClient() as c:
        backoff = 0.5
        for _ in range(3):
            try:
                async for chunk in c.chat.stream(prompt):
                    yield chunk
                return
            except APIError as e:
                if getattr(e, 'status', 0) >= 500:
                    await asyncio.sleep(backoff)
                    backoff *= 2
                else:
                    raise
```

zoe: TS should show AbortController to cancel streaming for UI timeouts. I pushed a tiny change with that.

```ts
// TS streaming + AbortController
import { RedwoodClient } from "@redwood/inference";
const client = new RedwoodClient();

export async function streamWithCancel(prompt: string, timeoutMs = 5000) {
  const controller = new AbortController();
  const t = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const stream = await client.chat.stream({ prompt, signal: controller.signal });
    for await (const chunk of stream) console.log(chunk);
  } finally {
    clearTimeout(t);
  }
}
```

chet: Go example to show cursor pagination + streaming tokens via channel. keep import path updated.

```go
// Go: cursor pagination (embeddings) + stream consumer
package docs

import (
  "context"
  "github.com/redwood/inference-go"
)

func PaginateEmbeddings(ctx context.Context, c *inference.Client, q string) ([]float64, error) {
  var all []float64
  cursor := ""
  for {
    resp, err := c.Embeddings(ctx, &inference.EmbeddingsRequest{Query: q, Cursor: cursor})
    if err != nil { return nil, err }
    all = append(all, resp.Embeddings...)
    if resp.NextCursor == "" { break }
    cursor = resp.NextCursor
  }
  return all, nil
}
```

